<script setup lang="ts">
/* eslint-disable @typescript-eslint/no-explicit-any -- content query shape is consumed by the existing session component boundary. */
import { api } from '#convex/api'
const route = useRoute(); const id = String(route.params.sessionId); const router = useRouter(); const { allowed, checkingAccess } = useLearnV2Access(); const content = import.meta.client ? useConvexQuery(api.learnV2SessionContent.getSessionContent, { studySessionId: id as never }, { enabled: allowed }) : { data: ref(null) }
const session = computed(() => content.data.value as any)
</script>
<template><main class="min-h-full"><section v-if="checkingAccess || !session" class="mx-auto max-w-2xl p-6" aria-live="polite">Preparing your focused session…</section><section v-else-if="!allowed" class="mx-auto max-w-2xl p-6">This learning experience is not available for this account.</section><LearnV2TodaySession v-else :candidate="{ studySessionId: id, sessionRevision: session.sessionRevision, contentRevision: session.revision, planRecordRevision: session.planRecordRevision, blueprintRecordRevision: session.blueprintRecordRevision, objectiveTitle: session.objective.title, capability: session.objective.capability, estimatedMinutes: session.objective.estimatedMinutes ?? 25, scheduledStartAt: 0, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone, reason: 'workspace', progress: { retained: 0, independent: 0, total: 0 } }" /><div class="mx-auto max-w-3xl px-4 pb-6"><button type="button" class="text-sm text-muted-foreground hover:text-foreground" @click="router.back">Exit session</button></div></main></template>
